CREATE TABLE refund_order(id BIGINT PRIMARY KEY AUTO_INCREMENT,refund_no VARCHAR(64) NOT NULL UNIQUE,business_key VARCHAR(128) NOT NULL UNIQUE,order_no VARCHAR(64) NOT NULL UNIQUE,payment_no VARCHAR(64) NULL,after_sale_id BIGINT NULL,amount_fen BIGINT NOT NULL,status VARCHAR(32) NOT NULL,reason VARCHAR(255) NOT NULL,channel_refund_no VARCHAR(64) NULL UNIQUE,refunded_at DATETIME(6) NULL,last_error VARCHAR(255) NULL,created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),CHECK(amount_fen>=0),FOREIGN KEY(order_no) REFERENCES trade_order(order_no),FOREIGN KEY(payment_no) REFERENCES payment_order(payment_no),FOREIGN KEY(after_sale_id) REFERENCES after_sale(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
